fn is_decimal_with_two_precision(s: &[u8]) -> bool {
    // We need at least three bytes: one for the '.' and two trailing characters.
    if s.len() < 3 {
        return false;
    }
    // Check if the byte at position len - 3 is a '.'
    s[s.len() - 3] == b'.'
}

